UploadErrorCode: {
  readonly INVALID_FILE_TYPE: 400;
  readonly TOO_MANY_FILES: 402;
  readonly INVALID_FILE_SIZE: 403;
  readonly TOO_LESS_FILES: 405;
  readonly TOO_LARGE: 413;
}

